SELECT * FROM coupon


        AND name LIKE CONCAT('%', #{name}, '%')


        AND type = #{type}


        AND status = #{status}


ORDER BY created_at DESC

SELECT * FROM coupon
WHERE status = 1
AND start_time <= #{currentTime}
AND end_time >= #{currentTime}
AND received_count < total_count
ORDER BY created_at DESC

SELECT COUNT(*) > 0 FROM coupon
WHERE coupon_id = #{couponId}
AND status = 1
AND start_time <= #{currentTime}
AND end_time >= #{currentTime}
AND received_count < total_count
